export function loadRows(): AttendanceRow[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      saveRows(SEED);
      return [...SEED];
    }
    const parsed = JSON.parse(raw) as AttendanceRow[];
    return Array.isArray(parsed) ? parsed.filter((r) => r.isActive !== false) : [...SEED];
  } catch {
    return [...SEED];
  }
}

export function saveRows(rows: AttendanceRow[]) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(rows));
}

export function genCode(rows: AttendanceRow[]): string {
  const day = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const prefix = `CC-${day}-`;
  let max = 0;
  rows.forEach((r) => {
    if (r.code.startsWith(prefix)) {
      const n = Number(r.code.slice(prefix.length));
      if (!Number.isNaN(n) && n > max) max = n;
    }
  });
  return `${prefix}${String(max + 1).padStart(3, '0')}`;
}

export function filterRows(
  rows: AttendanceRow[],
  opts: { search?: string; status?: string; route?: string; onlyOutZone?: boolean },
): AttendanceRow[] {
  const search = (opts.search ?? '').trim().toLowerCase();
  const status = (opts.status ?? '').trim();
  const route = (opts.route ?? '').trim();
  const onlyOutZone = opts.onlyOutZone === true;
  return rows.filter((r) => {
    if (status && r.status !== status) return false;
    if (route && r.route !== route) return false;
    if (onlyOutZone && r.inZone) return false;
    if (!search) return true;
    const blob = [
      r.code,
      r.userName,
      r.route,
      r.status,
      r.kmPoint,
      r.note,
      String(r.lat),
      String(r.lng),
    ]
      .join(' ')
      .toLowerCase();
    return blob.includes(search);
  });
}

export function formatGps(lat: number | null | undefined, lng: number | null | undefined): string {
  if (lat == null || lng == null || Number.isNaN(lat) || Number.isNaN(lng)) return '—';
  return `${Number(lat).toFixed(5)}, ${Number(lng).toFixed(5)}`;
}
