import React, { useEffect, useMemo, useState } from 'react';
import { useShellPageTitle } from '../../router/useShellPageTitle';
import { useDispatch } from 'react-redux';
import {
  Button,
  Input,
  LeaveConfirmModal,
  Select,
  Slideout,
  dispatchAppToast,
  useLeaveConfirm,
} from '@linm-soft-org/linm-web-common-components';
import { attendanceService } from '../../services/attendance/attendanceService';
import { attendanceListPermissions } from '../../services/attendance/permissions';
import type { AttendanceDto } from '../../services/attendance/responseModel';
import { RmmsOrgFormFields } from '../../filters/RmmsOrgFormFields';
import {
  orgFromDto,
  orgPersistPayload,
  type RmmsOrgFormValue,
} from '../../filters/rmmsOrgForm';
import {
  ATTENDANCE_STATUSES,
  EMPTY_FORM,
  genCode,
  loadRows,
  type AttendanceRow,
} from '../../demo/attendanceStore';
import styles from './AttendanceFormSlideout.module.css';

export type AttendanceFormMode = 'create' | 'edit' | 'view' | 'copy';

type FormState = Omit<AttendanceRow, 'id'>;

type Props = {
  open: boolean;
  mode: AttendanceFormMode;
  editing: AttendanceDto | null;
  onClose: () => void;
  onSaved: () => void;
  onModeChange: (mode: AttendanceFormMode) => void;
};

const REQUIRED: (keyof FormState)[] = [
  'userName',
  'route',
  'checkInAt',
  'lat',
  'lng',
  'status',
];

function orgOf(form: FormState): RmmsOrgFormValue {
  return {
    zoneOrgCode: form.zoneOrgCode ?? '',
    zoneOrgName: form.zoneOrgName ?? '',
    vpOrgCode: form.vpOrgCode ?? '',
    vpOrgName: form.vpOrgName ?? '',
    assigneeCode: form.assigneeCode ?? '',
    assigneeName: form.assigneeOrgName ?? '',
    routeCode: form.routeCode || form.route || '',
    routeName: '',
  };
}

const MODE_TITLE: Record<AttendanceFormMode, string> = {
  create: 'Tạo mới chấm công',
  edit: 'Sửa chấm công',
  view: 'Xem chấm công',
  copy: 'Sao chép chấm công',
};

const MODE_HINT: Record<AttendanceFormMode, string> = {
  create: 'Nhập log check-in. Mã chấm công do hệ thống sinh khi lưu.',
  edit: 'Chỉnh sửa — các trường bắt buộc đánh dấu *.',
  view: 'Chế độ xem — trường dùng readOnly (không disabled xám).',
  copy: 'Sao chép từ bản ghi gốc — mã mới khi lưu.',
};

function toLocalInput(iso: string): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function fromLocalInput(local: string): string {
  if (!local) return new Date().toISOString();
  const d = new Date(local);
  return Number.isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
}

function fromDto(dto: AttendanceDto, asCopy: boolean): FormState {
  return {
    code: asCopy ? genCode(loadRows()) : dto.code,
    userName: dto.userName,
    route: dto.route,
    ...orgFromDto({ ...dto, route: dto.route }),
    assigneeOrgName: dto.assigneeOrgName ?? '',
    checkInAt: dto.checkInAt,
    kmPoint: dto.kmPoint ?? '',
    lat: dto.lat,
    lng: dto.lng,
    inZone: dto.inZone,
    status: dto.status,
    note: dto.note ?? '',
    updatedAt: dto.updatedAt ?? '',
    isActive: dto.isActive !== false,
  };
}

export const AttendanceFormSlideout: React.FC<Props> = ({
  open,
  mode,
  editing,
  onClose,
  onSaved,
  onModeChange,
}) => {
  const dispatch = useDispatch();
  const perms = attendanceListPermissions();
  const readOnly = mode === 'view';
  const [form, setForm] = useState<FormState>({ ...EMPTY_FORM });
  const [currentId, setCurrentId] = useState<string | null>(null);
  const [invalid, setInvalid] = useState<Set<string>>(new Set());
  const [showBanner, setShowBanner] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const { guardedNavigate, leaveConfirmModalProps } = useLeaveConfirm({
    isDirty: dirty && !readOnly,
  });

  useEffect(() => {
    if (!open) return;
    let cancelled = false;
    const boot = async () => {
      setLoading(true);
      setInvalid(new Set());
      setShowBanner(false);
      setDirty(false);
      try {
        if (mode === 'create') {
          setCurrentId(null);
          setForm({
            ...EMPTY_FORM,
            code: '(tự sinh)',
            checkInAt: new Date().toISOString(),
            updatedAt: '',
          });
          return;
        }
        if (!editing) return;
        if (mode === 'copy' || mode === 'edit' || mode === 'view') {
          const dto = await attendanceService.getById(editing.id);
          if (cancelled) return;
          setCurrentId(mode === 'copy' ? null : dto.id);
          setForm(fromDto(dto, mode === 'copy'));
        }
      } catch {
        if (!cancelled) onClose();
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void boot();
    return () => {
      cancelled = true;
    };
  }, [open, mode, editing, onClose]);

  const statusOptions = useMemo(
    () => ATTENDANCE_STATUSES.map((s) => ({ value: s, label: s })),
    [],
  );
  const inZoneOptions = useMemo(
    () => [
      { value: 'true', label: 'Trong zone' },
      { value: 'false', label: 'Ngoài zone' },
    ],
    [],
  );

  const updateField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    if (readOnly) return;
    setDirty(true);
    setForm((prev) => ({ ...prev, [key]: value }));
    setInvalid((prev) => {
      const next = new Set(prev);
      next.delete(String(key));
      return next;
    });
  };

  const validate = (): boolean => {
    const bad = new Set<string>();
    REQUIRED.forEach((key) => {
      const val = form[key];
      if (val === '' || val == null || (typeof val === 'string' && !val.trim())) {
        bad.add(key);
      }
    });
    if (Number.isNaN(Number(form.lat))) bad.add('lat');
    if (Number.isNaN(Number(form.lng))) bad.add('lng');
    setInvalid(bad);
    setShowBanner(bad.size > 0);
    return bad.size === 0;
  };

  const handleClose = () => {
    guardedNavigate(() => onClose());
  };

  const handleSave = async () => {
    if (readOnly) return;
    if (mode === 'edit' && !perms.canUpdate) return;
    if ((mode === 'create' || mode === 'copy') && !perms.canCreate) return;
    if (!validate()) return;
    setSaving(true);
    try {
      const payload = {
        userName: form.userName.trim(),
        route: (form.routeCode || form.route).trim(),
        ...orgPersistPayload(orgOf(form)),
        checkInAt: form.checkInAt,
        kmPoint: form.kmPoint.trim(),
        lat: Number(form.lat),
        lng: Number(form.lng),
        inZone: form.inZone,
        status: form.status,
        note: form.note,
      };
      if (mode === 'edit' && currentId) {
        await attendanceService.update(currentId, payload);
      } else {
        await attendanceService.create(payload);
      }
      setDirty(false);
      dispatchAppToast(dispatch, {
        message: 'Đã lưu bản ghi chấm công',
        type: 'success',
      });
      onSaved();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Lưu chấm công thất bại',
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  };

  const fieldClass = (key: string) =>
    [styles.field, invalid.has(key) ? styles.fieldInvalid : ''].filter(Boolean).join(' ');

  const titleNode = (
    <div className={styles.titleBlock}>
      <h2 className={styles.title}>{MODE_TITLE[mode]}</h2>
      <span className={styles.badge}>{mode}</span>
    </div>
  );

  const body = loading ? (
    <div className={styles.loading} data-testid="attendance-form-loading">
      Đang tải…
    </div>
  ) : (
    <>
      <p className={styles.z1h} data-testid="attendance-form-z1h">
        {MODE_HINT[mode]} · Slideout · footer actions only · 10 controls
      </p>
      <div className={`${styles.banner} ${showBanner ? styles.bannerOn : ''}`}>
        Vui lòng nhập đủ các trường bắt buộc (đánh dấu *).
      </div>
      <div className={styles.z2} data-testid="attendance-form-z2">
        <section>
          <h3 className={styles.sectionTitle}>Thông tin chấm công</h3>
          <div className={styles.fields}>
            <div className={fieldClass('code')}>
              <Input
                label="Mã chấm công"
                value={form.code}
                readOnly
                fullWidth
                data-testid="attendance-field-code"
              />
            </div>
            <div className={fieldClass('status')}>
              {readOnly ? (
                <Input
                  label="Trạng thái công"
                  required
                  value={form.status}
                  readOnly
                  fullWidth
                  data-testid="attendance-field-status"
                />
              ) : (
                <Select
                  label="Trạng thái công"
                  required
                  value={form.status}
                  options={statusOptions}
                  onChange={(e) => updateField('status', e.target.value)}
                  fullWidth
                  data-testid="attendance-field-status"
                />
              )}
              <span className={styles.fieldError}>Bắt buộc</span>
            </div>
            <div className={`${fieldClass('userName')} ${styles.span2}`}>
              <Input
                label="Nhân viên"
                required
                value={readOnly ? (editing?.userDisplayName?.trim() || form.userName) : form.userName}
                readOnly={readOnly}
                onChange={(e) => updateField('userName', e.target.value)}
                fullWidth
                data-testid="attendance-field-userName"
              />
              <span className={styles.fieldError}>Bắt buộc</span>
            </div>
            <RmmsOrgFormFields
              testIdPrefix="attendance"
              value={orgOf(form)}
              disabled={readOnly}
              routeError={invalid.has('route') ? 'Bắt buộc' : undefined}
              onChange={(next) => {
                setForm((f) => ({
                  ...f,
                  zoneOrgCode: next.zoneOrgCode,
                  zoneOrgName: next.zoneOrgName,
                  vpOrgCode: next.vpOrgCode,
                  vpOrgName: next.vpOrgName,
                  assigneeCode: next.assigneeCode,
                  assigneeOrgName: next.assigneeName,
                  routeCode: next.routeCode,
                  route: next.routeCode,
                }));
                setDirty(true);
              }}
            />
            <div className={fieldClass('checkInAt')}>
              <Input
                label="Thời điểm check-in"
                required
                type="datetime-local"
                value={toLocalInput(form.checkInAt)}
                readOnly={readOnly}
                onChange={(e) => updateField('checkInAt', fromLocalInput(e.target.value))}
                fullWidth
                data-testid="attendance-field-checkInAt"
              />
              <span className={styles.fieldError}>Bắt buộc</span>
            </div>
            <div className={styles.field}>
              <Input
                label="Lý trình (Km+)"
                value={form.kmPoint}
                readOnly={readOnly}
                onChange={(e) => updateField('kmPoint', e.target.value)}
                placeholder="VD: km12+000"
                fullWidth
                data-testid="attendance-field-kmPoint"
              />
            </div>
            <div className={fieldClass('inZone')}>
              {readOnly ? (
                <Input
                  label="Trong zone (InZone)"
                  value={form.inZone ? 'Trong zone' : 'Ngoài zone'}
                  readOnly
                  fullWidth
                  data-testid="attendance-field-inZone"
                />
              ) : (
                <Select
                  label="Trong zone (InZone)"
                  value={form.inZone ? 'true' : 'false'}
                  options={inZoneOptions}
                  onChange={(e) => updateField('inZone', e.target.value === 'true')}
                  fullWidth
                  data-testid="attendance-field-inZone"
                />
              )}
            </div>
          </div>
        </section>
        <section>
          <h3 className={styles.sectionTitle}>Định vị GPS</h3>
          <div className={styles.fields}>
            <div className={fieldClass('lat')}>
              <Input
                label="Vĩ độ (Lat)"
                required
                type="number"
                step="0.00001"
                value={form.lat ?? ''}
                readOnly={readOnly}
                onChange={(e) =>
                  updateField('lat', e.target.value === '' ? 0 : Number(e.target.value))
                }
                fullWidth
                data-testid="attendance-field-lat"
              />
              <span className={styles.fieldError}>Bắt buộc</span>
            </div>
            <div className={fieldClass('lng')}>
              <Input
                label="Kinh độ (Lng)"
                required
                type="number"
                step="0.00001"
                value={form.lng ?? ''}
                readOnly={readOnly}
                onChange={(e) =>
                  updateField('lng', e.target.value === '' ? 0 : Number(e.target.value))
                }
                fullWidth
                data-testid="attendance-field-lng"
              />
              <span className={styles.fieldError}>Bắt buộc</span>
            </div>
            <div className={`${styles.field} ${styles.span2}`}>
              <Input
                label="Ghi chú"
                value={form.note}
                readOnly={readOnly}
                onChange={(e) => updateField('note', e.target.value)}
                fullWidth
                data-testid="attendance-field-note"
              />
            </div>
          </div>
        </section>
      </div>
    </>
  );

  const footer = (
    <div className={styles.z3} data-testid="attendance-form-z3">
      {readOnly ? (
        <>
          <Button variant="secondary" onClick={handleClose} data-testid="attendance-btn-close">
            Đóng
          </Button>
          {currentId && perms.canCreate ? (
            <Button
              variant="secondary"
              onClick={() => onModeChange('copy')}
              data-testid="attendance-btn-to-copy"
            >
              Sao chép
            </Button>
          ) : null}
          {currentId && perms.canUpdate ? (
            <Button
              variant="primary"
              onClick={() => onModeChange('edit')}
              data-testid="attendance-btn-to-edit"
            >
              Sửa
            </Button>
          ) : null}
        </>
      ) : (
        <>
          <Button variant="secondary" onClick={handleClose} data-testid="attendance-btn-cancel">
            Hủy
          </Button>
          <Button
            variant="primary"
            onClick={() => void handleSave()}
            loading={saving}
            data-testid="attendance-btn-save"
          >
            Lưu
          </Button>
        </>
      )}
    </div>
  );

  useShellPageTitle(MODE_TITLE[mode]);
  return (
    <>
      <Slideout
        isOpen={open}
        onClose={handleClose}
        title={titleNode}
        width={720}
        customFooter={footer}
        data-testid="rmms-attendance-form-slideout"
      >
        {body}
      </Slideout>
      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </>
  );
};

export default AttendanceFormSlideout;
