import { attendanceEndpoint } from './endpoint';
import type { CreateAttendanceRequest, UpdateAttendanceRequest } from './requestModel';
import type { AttendanceDto, AttendancePagedResult } from './responseModel';
import {
  ATTENDANCE_STATUSES,
  filterRows,
  genCode,
  loadRows,
  saveRows,
  type AttendanceRow,
} from '../../demo/attendanceStore';
import { ROAD_ROUTE_SEED } from './lookups';

function toDto(row: AttendanceRow): AttendanceDto {
  return {
    id: row.id,
    code: row.code,
    userName: row.userName,
    route: row.route,
    checkInAt: row.checkInAt,
    kmPoint: row.kmPoint,
    lat: row.lat,
    lng: row.lng,
    inZone: row.inZone,
    status: row.status,
    note: row.note,
    updatedAt: row.updatedAt,
    isActive: row.isActive,
  };
}

function localList(params?: {
  search?: string;
  status?: string;
  route?: string;
  onlyOutZone?: boolean;
  page?: number;
  pageSize?: number;
}): AttendancePagedResult {
  const page = params?.page ?? 1;
  const pageSize = params?.pageSize ?? 50;
  const filtered = filterRows(loadRows(), {
    search: params?.search ?? '',
    status: params?.status ?? '',
    route: params?.route ?? '',
    onlyOutZone: params?.onlyOutZone === true,
  });
  const start = (page - 1) * pageSize;
  const items = filtered.slice(start, start + pageSize).map(toDto);
  const totalCount = filtered.length;
  return {
    items,
    totalCount,
    page,
    pageSize,
    totalPages: Math.max(1, Math.ceil(totalCount / pageSize)),
  };
}

function assertWritable(data: CreateAttendanceRequest) {
  const code = data.route.trim();
  if (code.toUpperCase() === 'QL.22') {
    throw new Error(
      'Tuyến QL.22 không thuộc danh mục tuyến đường CUC2. Chọn mã tuyến hợp lệ (ví dụ QL.1).',
    );
  }
  if (!ROAD_ROUTE_SEED.some((r) => r.value === code)) {
    throw new Error(`Tuyến «${code}» không tồn tại trong danh mục tuyến đường đang hiệu lực.`);
  }
  if (!ATTENDANCE_STATUSES.includes(data.status as (typeof ATTENDANCE_STATUSES)[number])) {
    throw new Error('Trạng thái công phải là Đúng tuyến, Lệch zone hoặc Thiếu điểm.');
  }
}

async function withFallback<T>(fn: () => Promise<T>, fallback: () => T): Promise<T> {
  try {
    return await fn();
  } catch {
    return fallback();
  }
}

export const attendanceService = {
  getList: (params?: {
    search?: string;
    status?: string;
    route?: string;
    onlyOutZone?: boolean;
    page?: number;
    pageSize?: number;
  }) => withFallback(() => attendanceEndpoint.getList(params), () => localList(params)),

  getById: (id: string) =>
    withFallback(
      () => attendanceEndpoint.getById(id),
      () => {
        const row = loadRows().find((r) => r.id === id || r.code === id);
        if (!row) throw new Error(`Không tìm thấy chấm công ${id}`);
        return toDto(row);
      },
    ),

  create: (data: CreateAttendanceRequest) =>
    withFallback(
      () => attendanceEndpoint.create(data),
      () => {
        assertWritable(data);
        const rows = loadRows();
        const row: AttendanceRow = {
          id: crypto.randomUUID(),
          code: genCode(rows),
          userName: data.userName,
          route: data.route,
          checkInAt: data.checkInAt,
          kmPoint: data.kmPoint ?? '',
          lat: data.lat,
          lng: data.lng,
          inZone: data.inZone,
          status: data.status,
          note: data.note ?? '',
          updatedAt: new Date().toISOString(),
          isActive: true,
        };
        saveRows([row, ...rows]);
        return toDto(row);
      },
    ),

  update: (id: string, data: UpdateAttendanceRequest) =>
    withFallback(
      () => attendanceEndpoint.update(id, data),
      () => {
        assertWritable(data);
        const rows = loadRows();
        const idx = rows.findIndex((r) => r.id === id || r.code === id);
        if (idx < 0) throw new Error(`Không tìm thấy chấm công ${id}`);
        const next: AttendanceRow = {
          ...rows[idx],
          userName: data.userName,
          route: data.route,
          checkInAt: data.checkInAt,
          kmPoint: data.kmPoint ?? '',
          lat: data.lat,
          lng: data.lng,
          inZone: data.inZone,
          status: data.status,
          note: data.note ?? '',
          isActive: data.isActive ?? rows[idx].isActive,
          updatedAt: new Date().toISOString(),
        };
        const copy = [...rows];
        copy[idx] = next;
        saveRows(copy);
        return toDto(next);
      },
    ),

  delete: (id: string) =>
    withFallback(
      () => attendanceEndpoint.delete(id),
      () => {
        const rows = loadRows().map((r) =>
          r.id === id || r.code === id ? { ...r, isActive: false } : r,
        );
        saveRows(rows);
      },
    ),
};
